#include <omp.h>
#include <cstddef>
#include <vector>

size_t findFirstEven(std::vector<int> const& x) {
    size_t best = x.size();  // Sentinel: "not found"

    #pragma omp parallel for reduction(min : best)
    for (size_t i = 0; i < x.size(); ++i) {
        if ((x[i] & 1) == 0 && i < best) {
            best = i;
        }
    }

    return best;
}
